using Microsoft.EntityFrameworkCore;
using SportsBooking.Application.Common;
using SportsBooking.Domain.Bookings;
using SportsBooking.Domain.Pitches;
using SportsBooking.Domain.Scheduling;

namespace SportsBooking.Application.Pitches;

/// <summary>A pitch together with the time zone of its club, which its slots are generated in (T04).</summary>
public sealed record PitchInZone(Pitch Pitch, TimeZoneInfo TimeZone);

/// <summary>
/// One slot generated by a pitch's schedule on a date, and what overlaps it.
/// <see cref="Blocked"/>: any block of the pitch overlaps it (US09). <see cref="Booked"/>: any confirmed booking overlaps
/// it (US18), even one made on an older grid after a slot length change (US17).
/// </summary>
public sealed record DaySlot(TimeSlot Slot, bool Blocked, bool Booked)
{
    /// <summary>Free for a player: nothing overlaps it and it has not started (US17). The only rule for "free".</summary>
    public bool IsFreeAt(DateTime nowUtc) => !Blocked && !Booked && !Slot.HasStartedBy(nowUtc);
}

/// <summary>
/// The one calculation of what a pitch's slots on a local date are and which of them are taken. The owner's preview
/// (US08), the free slots a player sees (US17) and the "has free slots" of the search (US16) all use it, so they can
/// never disagree. Slots come from <see cref="Pitch.SlotsOn"/>; blocks and confirmed bookings of all the given pitches
/// are read with one query each.
/// </summary>
public sealed class PitchDayCalendar(IAppDbContext dbContext)
{
    public async Task<IReadOnlyDictionary<Guid, IReadOnlyList<DaySlot>>> SlotsAsync(
        IReadOnlyCollection<PitchInZone> pitches,
        DateOnly date,
        CancellationToken cancellationToken)
    {
        var generated = pitches.ToDictionary(item => item.Pitch.Id, item => item.Pitch.SlotsOn(date, item.TimeZone));
        var withSlots = generated.Where(entry => entry.Value.Count > 0).ToList();
        var result = generated.ToDictionary(entry => entry.Key, _ => (IReadOnlyList<DaySlot>)[]);
        if (withSlots.Count == 0)
        {
            return result;
        }

        var ids = withSlots.Select(entry => entry.Key).ToList();
        var from = withSlots.Min(entry => entry.Value[0].StartsAtUtc);
        var to = withSlots.Max(entry => entry.Value[^1].EndsAtUtc);
        var blocks = (await dbContext.Blocks.AsNoTracking()
                .Where(block => ids.Contains(block.PitchId) && block.StartsAt < to && from < block.EndsAt)
                .ToListAsync(cancellationToken))
            .ToLookup(block => block.PitchId);
        var bookings = (await dbContext.Bookings.AsNoTracking()
                .Where(booking => ids.Contains(booking.PitchId) && booking.Status == BookingStatus.Confirmed && booking.StartsAt < to && from < booking.EndsAt)
                .ToListAsync(cancellationToken))
            .ToLookup(booking => booking.PitchId);

        foreach (var (pitchId, slots) in withSlots)
        {
            result[pitchId] = slots
                .Select(slot => new DaySlot(
                    slot,
                    blocks[pitchId].Any(block => block.Overlaps(slot.StartsAtUtc, slot.EndsAtUtc)),
                    bookings[pitchId].Any(booking => booking.Overlaps(slot.StartsAtUtc, slot.EndsAtUtc))))
                .ToList();
        }

        return result;
    }
}
